-- GENERATED by `wfj generate` from data/gossip/gossip-b3.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["b30228e0fd6cb3a4"] = { "FINISCI L'INCANTESIMO, STAGHELM! NON POSSO TENERE AL LORO POSTO I GLIFI DI PROTEZIONE ANCORA A LUNGO! INVOCA LE RADICI!", "." },
  ["b30934ed36d1f0f7"] = { "Mmmm... hai proprio un aspetto appetitoso.", "." },
  ["b318c3d5db4cb7a7"] = { "Porta questo registro a una mia vecchia conoscenza a Tanaris. Si chiama Narain Soothfancy: un sensitivo terribile, terribile, ma un ingegnere straordinario! Dovrebbe riuscire a capirci qualcosa.\n\nNon serve ringraziarmi, {name}. È il minimo che potessi fare.\n\nBuona giornata!", "." },
  ["b31a65cb6e5c35c7"] = { "<Patetico/Patetica> <rammollito/rammollita> dei Reietti. Vuoi vedere il mio padrone? E sia.", "." },
  ["b334b704d30b05a5"] = { "I Maneweaver praticano le loro professioni nella loro casa sulla strada per Darnassus. Nadyia è un'ottima insegnante di Conciatura. Dovresti vedere cosa può insegnarti.", "." },
  ["b3385d446b9a389e"] = { "Come, amore mio? Come troverò la forza di affrontare le ere del mondo senza te al mio fianco...", "." },
  ["b33f452179a89936"] = { "Guarda questo drago caduto, {race}. La potenza dell'⟦Horde=Orda⟧ è indiscutibile!", "." },
  ["b3433dc4e1f8ce59"] = { "Qui! Dentro la stanza. Hai trovato la chiave delle mie catene? Ce l'ha l'umano Borhuin.", "." },
  ["b34452136ec2b588"] = { "Ci sono molti segreti che si possono svelare con pazienza e determinazione. Ora, cominciamo...", "." },
  ["b3475be62577e0b6"] = { "Bende? Perché, hai intenzione di sopravvivere abbastanza a lungo da averne bisogno? Ah! Molto bene, {race}, te lo dirò. Delle $2080w Bende di Lana necessarie, ne abbiamo raccolte $2079w. Inoltre, a oggi abbiamo ricevuto $2085w Bende di Telamagica su $2086w, e $2089w Bende di Telarunica sulle $2090w richieste.", "." },
  ["b354b3516420ac30"] = { "Una leggenda vivente...", "." },
  ["b36080960520ba9b"] = { "Spero che tu sia qui per andare nella ⟦Alterac Valley=Valle d'Alterac⟧, {name}. Ci serve tutto l'aiuto possibile.", "." },
  ["b36136b72faacb48"] = { "Unisciti a me: insieme intrecceremo gli spiriti della forgia e troveremo la vera forma che il metallo cerca.", "." },
  ["b3735901651d3cd2"] = { "Se devo insegnarti l'Erbalismo, almeno renditi utile. Ho una commissione da farti sbrigare.\r\n\nPer essere una città di maghi, Dalaran ha un interesse sorprendente per la botanica. I Kirin Tor se ne stanno per conto loro, ma mi piacerebbe tanto avere un campione della loro vegetazione infusa di mana.\r\n\nÈ chiaro che sei a tuo agio dove la gente non ti vuole: forse potresti trovare un modo per entrare in città. Se ci riesci, riportami qualunque cosa cresca nel loro giardino centrale.", "." },
  ["b37506ffa7172809"] = { "A questo punto, evocherò qualcuno per esaminare il ciondolo, e troverà un compartimento nascosto...", "." },
  ["b37ac708b29da6af"] = { "Aiuto! I troll hanno catturato me e la mia banda, e vogliono sacrificarci!\n\nTiraci fuori di qui e ti darò tutto quello che vuoi.", "." },
  ["b37e8ae190eaa244"] = { "La guerra ha i suoi costi, {class}... costi spesso trascurati. Quei costi sono gli orfani: bambini che hanno perso i genitori nei troppi conflitti che infuriano in tutta Azeroth. I bambini che non hanno nessun altro a cui rivolgersi vengono spesso a vivere qui finché non sono abbastanza grandi da cavarsela da soli.\n\nUna settimana all'anno, in primavera, l'⟦Alliance=Alleanza⟧ si prende il tempo di restituire qualcosa a questi innocenti. Questo periodo si chiama Children's Week.", "." },
  ["b38033d4e0514d5f"] = { "Il mio scettro... Dopo tanti anni... L'hai recuperato! Sarai davvero la salvezza di questo luogo...\n\nAscoltami bene, {name}. La testa e l'asta dello scettro possono essere riunite in un unico oggetto solo presso la pietra di Maraudon.", "." },
  ["b38d02ee74a46147"] = { "{name}! Finalmente!\n\nDevi prendere questo segnalatore e piantarlo nel cratere orientale del campo di battaglia centrale. Il mio stormo attaccherà quando il segnalatore trasmetterà le sue coordinate!", "." },
  ["b38f53df7f72a691"] = { "Stalagg uccidere!", "." },
  ["b391a05cb38301ad"] = { "È stato un bel carico, ma ora posso fare scorta di rifornimenti per il viaggio di ritorno nel Cratere. Dovrei anche riuscire a scaricare un po' di questa merce esotica.", "." },
  ["b39d67a2a621fb12"] = { "Pane appena sfornato in vendita!", "." },
  ["b3a736fe7a9d92c0"] = { "Diventa il mentore di uno dei nostri orfani durante la Week of the Wardens! Urrà!", "." },
  ["b3a7a9e99d936f73"] = { "Ho già visitato ⟦Ironforge=Forgiardente⟧. C'è un odore strano laggiù.", "." },
  ["b3a86e23d6ab3ccd"] = { "Ti ascolto, Demitrian.", "." },
  ["b3aea61a5482e62d"] = { "Esatto. Ti sto davanti in una forma che puoi comprendere, mortale. Di certo non potresti sopportare di trovarti al cospetto del drago noto come Vaelastrasz.\n\n<Vaelan ride.>\n\nVuoi che continui?", "." },
  ["b3af757b998cf10c"] = { "Dov'è l'anziano Moonwarden?", "." },
  ["b3b246392c490a34"] = { "Un'altra interruzione. Come dovrei riuscire a lavorare così? Non rispondere: ti sembra che m'importi quello che hai da dire? Perché non vai a disturbare il signor Pezzo-Grosso?", "." },
  ["b3b43e906ca6155d"] = { "Cra!", "." },
  ["b3b870a0a05ecd63"] = { "Abbiamo una scorta minima di rifornimenti per ricostruire la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧. Ne serviranno molti di più prima di poterla riparare e tornare in battaglia.", "." },
  ["b3bb9c6d86a378f6"] = { "Karu, per favore, mi aiuti a togliermi di dosso queste api? Pungono!", "." },
  ["b3c76744e9c6503f"] = { "Che forte.", "." },
  ["b3c92c3adc806689"] = { "Ah, questa stoffa di Darnassus è la migliore!", "." },
  ["b3cc6cba7ff8b67a"] = { "Mi piace come ragioni! Andiamocene di qui!", "." },
  ["b3d1ff89cddb0395"] = { "Voglio affidare il felino corrotto a Winna.", "." },
  ["b3da132f25919061"] = { "Ancora qualcuno che si dà all'Alchimia, mmm. Dubito che la tua abilità sia grande quanto la mia, quindi forse posso insegnarti qualche tecnica come si deve.", "." },
  ["b3e192af0a2a32f8"] = { "Salute, sono Elaadrin Evengale, l'attuale magistro supremo dell'High Order. Come posso aiutarti?", "." },
  ["b3e3d9e84bd033bc"] = { "Tu ci proteggerai dalla malvagia padrona, sì!", "." },
  ["b3e786d0a7b69aaf"] = { "All'inizio ho aperto bottega nel ⟦Magic Quarter=Quartiere della Magia⟧, ma lì c'era parecchio rumore. Qui è decisamente meglio, a parte qualche studente insistente che riesce ancora a scovarmi, nonostante il trasloco.", "." },
})
